cat > scripts/automatic-benchmark.mjs <<'EOF'
// Read-only real-project context sampling and identical disposable hook fixtures.
import fs from 'node:fs';import os from 'node:os';import path from 'node:path';
import {execFileSync,spawn} from 'node:child_process';import {pathToFileURL,fileURLToPath} from 'node:url';
const source=path.resolve(fileURLToPath(new URL('..',import.meta.url)));
const percentile=(xs,p)=>[...xs].sort((a,b)=>a-b)[Math.min(xs.length-1,Math.floor(xs.length*p))];
const summary=xs=>({n:xs.length,median:percentile(xs,.5),p95:percentile(xs,.95),min:Math.min(...xs),max:Math.max(...xs)});
if(process.argv[2]==='worker'){
 const [product,root,mode,action]=process.argv.slice(3);
 const core=await import(pathToFileURL(path.join(product,'src/core.js'))),util=await import(pathToFileURL(path.join(product,'src/util.js')));
 const repo={...util.repoAt(root),dir:path.join(root,'.dip'),config:{...JSON.parse(fs.readFileSync(path.join(root,'.dip/config.json'))),workflow:mode}};
 if(action==='context'){
  const samples=[];let result;for(let i=0;i<5;i++){const s=performance.now();result=core.compactContext(repo,null);samples.push(performance.now()-s)}
  console.log(JSON.stringify({ms:summary(samples),bytes:Buffer.byteLength(JSON.stringify(result)),recentBytes:Buffer.byteLength(JSON.stringify(result.recent||[])),truncated:result.truncated}));
 }else if(action==='hook'){
  const {handleHook}=await import(pathToFileURL(path.join(product,'src/automation.js')));
  const samples=[],db=[],reads=[];
  const task=process.env.DIP_BENCH_TASK;
  for(let i=0;i<30;i++){
   let s=performance.now();const rt=new core.Runtime();rt.register(repo);rt.close();db.push(performance.now()-s);
   s=performance.now();core.taskRead(repo,task);reads.push(performance.now()-s);
   s=performance.now();handleHook({cwd:root,session_id:'bench',tool_use_id:'p'+i,hook_event_name:'PostToolUse',tool_name:'Bash',tool_input:{command:'rg -n TODO src'}},'fixture');samples.push(performance.now()-s);
  }
